	title 'MoreKidding'************************************************************************ MoreKidding.ASM** Copyright Apple Computer, Inc. 1988* All Rights Reserved** By Steven Glass** This is a file that contains code simulate the stack entry point* in the early versions of the OS that did not have one.** This code has two parts, the first installs a jml at the stack* entry point for the OS.  It is run at tool init time.** The second is the code that is entered by the jump.************************************************************************	blanks off	include 'all.macros'OS_Kind	equ $E100BCOS_Boot	equ $E100BDOS_Flag	equ $E100BEOS_StackEntry	equ $E100B0drvr_dib_ptr	equ $00BD24*****************************************************************FixOSStackEntry	PROC EXPORT** Description*** Inputs:*	none** Outputs:*	none** External Refs:	import FakeStackEntry** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda >MyJump	sta >OS_StackEntry	lda >MyJump+2	sta >OS_StackEntry+2	rtlMyJump	jml FakeStackEntry	ENDP*****************************************************************FakeStackEntry	PROC** This is the code that is run when someone calls the OS* stack entry point and the OS is not in place.** The way this code works is to generate an inline OS call* on the stack.  the code is called with the equivalent to * a JSL and when it returns, the stack is cleaned up and* control returns to the calling routine just as if the * stack entry point existed.*** Inputs:*	LONG : ParamBlockPtr*	WORD : CallNumber** Outputs:*	a-reg : error code*	carry : error state*	z-flag : error state** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackTheJSL	LONGTheCall	wordThePtr	longTheRTL	wordRTLAdr	block 3inCallNumber	wordinParamPtr	long;; Push the code to call the OS on the stack.;	ldx #BytesToPush-2PushMore	lda >TheCode,x	pha	dex	dex	bpl PushMore;; copy the inputs from the stack into the code block (also on the stack);	lda inCallNumber,s	sta TheCall,s	lda inParamPtr,s	sta ThePtr,s	lda inParamPtr+2,s	sta ThePtr+2,s;; Move the real RTL address up so we can easily strip the inputs; off the stack later.;	lda RTLAdr,s	sta RTLAdr+6,s	lda RTLAdr+1,s	sta RTLAdr+6+1,s;; Make the OS call using the code now on the stack.  Note the; code starts at S+1 on the stack.  But since the RTL adds; 1 to the address before xfering control, we can use it; as is.;	tsc	jsl CallIt	tay	; save error code in y;; Pull the code and the inputs off the stack;	ldx #BytesToPush-2+6PullMore	pla	dex	dex	bpl PullMore	tya	restore carry and a-reg	cmp #1	rtl;; Xfer control to the place on the stack indicated by the a-reg;CallIt	pea 0000	; push 3 bytes on stack with highest = 0	phb	sta 1,s	; overstore low 2 and xfer	rtl	TheCode	jsl $E100A8	dc.w 0	dc.l 0	rtl	dc.b 0	; extra byte to make it evenBytesToPush	equ *-TheCode	ENDP	END